  "claim": {
    "component_id": "C015.main",
    "value": "If histories remain unreliable or identify no recurring actionable problem, a presumed friction fix should not be selected.",
    "scope": "Either stated condition triggers withholding a presumed product fix.",
    "provenance": {
      "refs": [
        {
          "source_id": "P008",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly supplies both alternative conditions and the restriction on selecting a presumed friction fix."
    }
  },
  "signal_basis": {
    "component_id": "C015.signal_basis",
    "value": "Inspection and clarification leave the histories unreliable, or the histories reveal no recurring actionable handoff problem.",
    "scope": "The bounded cohort's histories, assessed for continuity, conflicting identities or versions, and unexplained transitions, as evidence for selecting the limited release.",
    "provenance": {
      "refs": [
        {
          "source_id": "P002",
          "role": "CONTEXT"
        },
