        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited bundle establishes the cohort, inspection procedure, requirement for a corroborated recurring actionable handoff problem, and either condition that leaves this requirement unmet."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C015.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This supported decision restriction does not require an unresolved empirical relation."
    }
  },
  "rationale": "The mapping makes corroborated identification of a recurring actionable handoff problem a prerequisite for selecting a narrow friction fix. Either observed condition leaves that evidential gate unmet, licensing withholding the presumed fix within this decision process.",
  "uncertainty": "Withholding the fix does not establish that no actual friction exists or that a fix could not help; neither conclusion is required by this claim.",
  "anomalies": []
